package org.firstinspires.ftc.teamcode.tuning;

import com.qualcomm.robotcore.eventloop.opmode.LinearOpMode;
import com.qualcomm.robotcore.eventloop.opmode.TeleOp;
import com.qualcomm.robotcore.hardware.Servo;
import com.qualcomm.robotcore.util.Range;

import org.firstinspires.ftc.teamcode.config.DeviceNames;
import org.firstinspires.ftc.teamcode.config.Tuned;

import java.util.Locale;

// Generated by refract-suite ftc-construct. PRACTICE ONLY. Setup program 3 (prerequisites G-1). Robot on a box.
// Each turret has its own yaw servo (team 2026-10-17). For each turret, front then back, the student moves the servo
// to: straight forward, straight left and straight right (square to the robot's sides: 90 deg each way), then as far
// left and right as it can go (just before the cable pulls tight or it touches a stop). From those:
//   <side>YawForward = the forward position, <side>YawPerDeg = (left - right) / 180 (+ = turret turns left),
//   <side>YawMaxDeg / MinDeg = each far end in degrees, LIMIT_MARGIN_DEG inside it.
// Forward should sit midway between left and right; if not by more than LINEAR_WARN_DEG the servo is not linear or a
// mark was off. Last, both turrets swing between straight right and straight left while filmed in 240 fps slow
// motion: yawDegPerS = 180 deg / the slower turret's time. A servo only moves after square is pressed.
@TeleOp(name = "3 Turret Servos", group = "19859 Setup")
public class TurretServos extends LinearOpMode {
    private static final double BIG = 0.01, SMALL = 0.001;
    private static final double FPS = 240;
    private static final double LIMIT_MARGIN_DEG = 5, LINEAR_WARN_DEG = 3;
    private static final String[] SIDES = {"front", "back"};
    private static final String[] AIMS = {"straight forward", "straight LEFT (90 deg, square to the robot's left side)",
            "straight RIGHT (90 deg, square to the robot's right side)", "as far LEFT as it can go", "as far RIGHT as it can go"};
    private static final int FORWARD = 0, LEFT = 1, RIGHT = 2, FAR_LEFT = 3, FAR_RIGHT = 4, PER_SIDE = 5;
    private static final int TIME_STEP = 2 * PER_SIDE, STEPS = TIME_STEP + 1;

    @Override
    public void runOpMode() {
        Guide g = new Guide(telemetry, 3);
        Servo[] servos = new Servo[2];
        String missing = "";
        String[] names = {DeviceNames.FRONT_YAW, DeviceNames.BACK_YAW};
        for (int i = 0; i < 2; i++) {
            try {
                servos[i] = hardwareMap.get(Servo.class, names[i]);
            } catch (IllegalArgumentException e) {
                missing += names[i] + " ";
            }
        }

        while (opModeInInit()) {
            g.header(0, 0, "Before you start");
            if (!missing.isEmpty()) g.notReady("servo names " + missing + "(program 1)");
            g.why("Aiming turns each turret by its servo: the code needs the servo position for every angle, how far each turret may turn, and how fast.");
            g.doThis("Robot on a box. Cables on the turrets routed as in a match.");
            g.say("Nothing moves until you press square on a step. Keep fingers away from the turrets.");
            g.doThis("Press START.");
            g.update();
        }
        if (isStopRequested() || !missing.isEmpty()) return;

        // position per side and aim; the first step starts from the measured forward position, else the middle
        double[][] pos = new double[2][PER_SIDE];
        boolean[][] live = new boolean[2][PER_SIDE];
        double[] start = {Tuned.frontYawForward, Tuned.backYawForward};
        for (int side = 0; side < 2; side++) java.util.Arrays.fill(pos[side], Double.isNaN(start[side]) ? 0.5 : start[side]);
        int step = 0, frames = 0;
        boolean swungLeft = false, timeStarted = false, recorded = false;
        String note = "";

        while (opModeIsActive()) {
            boolean next = gamepad1.crossWasPressed(), back = gamepad1.triangleWasPressed(), square = gamepad1.squareWasPressed();
            boolean bigUp = gamepad1.rightBumperWasPressed(), bigDown = gamepad1.leftBumperWasPressed();
            boolean smallUp = gamepad1.rightTriggerWasPressed(), smallDown = gamepad1.leftTriggerWasPressed();
            boolean frameUp = gamepad1.dpadUpWasPressed(), frameDown = gamepad1.dpadDownWasPressed();
            if (next || back) note = "";
            if (back && step > 0 && step <= TIME_STEP) {
                step--;
                timeStarted = false;
            }

            if (step < TIME_STEP) {
                int side = step / PER_SIDE, aim = step % PER_SIDE;
                if (square) live[side][aim] = true;
                pos[side][aim] = Range.clip(pos[side][aim] + (bigUp ? BIG : 0) - (bigDown ? BIG : 0)
                        + (smallUp ? SMALL : 0) - (smallDown ? SMALL : 0), 0, 1);
                if (live[side][aim]) servos[side].setPosition(pos[side][aim]);

                g.header(step + 1, STEPS, (side == 0 ? "Front" : "Back") + " turret: " + AIMS[aim].split(" \\(")[0]);
                g.why(aim == FORWARD ? "Straight forward is 0 deg: every aim is counted from here."
                        : aim <= RIGHT ? "Two known angles give the servo position per degree."
                        : "The code never turns the turret past these ends (minus " + (int) LIMIT_MARGIN_DEG + " deg).");
                g.goal(aim <= RIGHT ? "The barrel points exactly " + AIMS[aim].split(" \\(")[0] + "." : "As far as it goes without the cable pulling tight or the servo buzzing.");
                g.doThis("Move the " + SIDES[side] + " turret " + AIMS[aim] + ".");
                if (aim == FORWARD) g.say("Sight along the barrel: it must point along the robot's centre line, toward the front.");
                if (aim == LEFT || aim == RIGHT) g.say("Hold a square against the robot's side: the barrel must be parallel to it.");
                if (aim >= FAR_LEFT) g.say("Watch the cable: stop where it is still loose. Stop before the servo buzzes or strains.");
                g.value("Position", String.format(Locale.US, "%.3f", pos[side][aim]) + (live[side][aim] ? "" : "   (not moving yet: press square)"));
                if (aim >= FAR_LEFT) {
                    double perDeg = (pos[side][LEFT] - pos[side][RIGHT]) / 180;
                    g.value("Angle", String.format(Locale.US, "%.0f deg", (pos[side][aim] - pos[side][FORWARD]) / perDeg));
                }
                g.keys("square = move the servo there, R1 / L1 = +/- 0.01, R2 / L2 = +/- 0.001, cross = save and next"
                        + (step > 0 ? ", triangle = back" : ""));
                if (next) {
                    if (!live[side][aim]) {
                        note = "press square first and look at the real position";
                    } else {
                        String problem = problem(aim, pos[side]);
                        if (!problem.isEmpty()) {
                            note = problem;
                        } else {
                            note = save(g, side, aim, pos[side]);
                            step++;
                        }
                        // the next step on this servo starts where this one ended
                        if (problem.isEmpty() && step < TIME_STEP && step / PER_SIDE == side && !live[side][step % PER_SIDE]) {
                            pos[side][step % PER_SIDE] = pos[side][aim];
                            live[side][step % PER_SIDE] = true;
                        }
                    }
                }
            } else if (step == TIME_STEP) {
                if (!timeStarted) {
                    swungLeft = false;
                    for (int side = 0; side < 2; side++) servos[side].setPosition(pos[side][RIGHT]);
                    timeStarted = true;
                }
                if (square) {
                    swungLeft = !swungLeft;
                    for (int side = 0; side < 2; side++) servos[side].setPosition(pos[side][swungLeft ? LEFT : RIGHT]);
                }
                frames = Math.max(0, frames + (frameUp ? 1 : 0) - (frameDown ? 1 : 0) + (bigUp ? 10 : 0) - (bigDown ? 10 : 0));
                g.header(STEPS, STEPS, "Turret turn speed");
                g.why("The servo says nothing back: the code knows a turret is on target once it has had this long to get there.");
                g.goal("A frame count from the slow-motion video (typically a few dozen frames).");
                g.doThis("Film both turrets from above in 240 fps slow motion (phone slo-mo) while pressing square:");
                g.say("each press swings both turrets: straight right -> straight left, next press back.");
                g.doThis("In the video, count the frames from the slower turret starting to move until it stops at the other side.");
                g.doThis("Enter that count here.");
                g.value("Turrets", swungLeft ? "LEFT" : "right");
                g.value("Frames", frames + String.format(Locale.US, "  (= %.3f s at 240 fps)", frames / FPS));
                g.keys("square = swing, dpad up / down = +/- 1 frame, R1 / L1 = +/- 10, cross = save, triangle = back");
                if (next) {
                    if (frames == 0) {
                        note = "enter the frame count first";
                    } else {
                        note = g.record("yawDegPerS", String.format(Locale.US, "%.1f", 180 / (frames / FPS)));
                        step++;
                    }
                }
            } else {
                if (!recorded) {
                    recorded = true;
                    for (int side = 0; side < 2; side++) servos[side].setPosition(pos[side][FORWARD]);
                    g.loadNextOnStop(this);
                }
                g.header(0, 0, "Done");
                g.finished("");
                g.say("Both turrets went back to straight forward.");
                for (int side = 0; side < 2; side++) {
                    double perDeg = (pos[side][LEFT] - pos[side][RIGHT]) / 180;
                    g.value(SIDES[side], String.format(Locale.US, "forward %.3f, %.5f per deg, %.0f to %.0f deg", pos[side][FORWARD], perDeg,
                            limit(pos[side], FAR_RIGHT), limit(pos[side], FAR_LEFT)));
                }
                g.value("yawDegPerS", String.format(Locale.US, "%.0f", 180 / Math.max(1e-9, frames / FPS)));
            }
            if (!note.isEmpty()) g.warn(note);
            g.update();
        }
    }

    // far end in degrees, LIMIT_MARGIN_DEG inside it
    private static double limit(double[] p, int aim) {
        double perDeg = (p[LEFT] - p[RIGHT]) / 180, deg = (p[aim] - p[FORWARD]) / perDeg;
        return deg - Math.signum(deg) * LIMIT_MARGIN_DEG;
    }

    // why this step cannot be saved yet ("" = it can)
    private static String problem(int aim, double[] p) {
        if (aim == RIGHT && Math.abs(p[LEFT] - p[RIGHT]) / 180 < 1e-4) return "left and right are the same position: move the turret to each side";
        if (aim == FAR_LEFT && limit(p, FAR_LEFT) <= 0) return "the far left end must be left of forward: move it left";
        if (aim == FAR_RIGHT && limit(p, FAR_RIGHT) >= 0) return "the far right end must be right of forward: move it right";
        return "";
    }

    // records one step's result; returns "" or what to show
    private static String save(Guide g, int side, int aim, double[] p) {
        String s = SIDES[side];
        switch (aim) {
            case FORWARD:
                return g.record(s + "YawForward", String.format(Locale.US, "%.4f", p[FORWARD]));
            case RIGHT: {
                double perDeg = (p[LEFT] - p[RIGHT]) / 180;
                String r = g.record(s + "YawPerDeg", String.format(Locale.US, "%.6f", perDeg));
                double offDeg = (p[FORWARD] - (p[LEFT] + p[RIGHT]) / 2) / perDeg;
                if (Math.abs(offDeg) <= LINEAR_WARN_DEG) return r;
                return String.format(Locale.US, "saved, but forward is %.1f deg off the middle of left and right: check the marks"
                        + " (triangle = redo), or the servo is not linear", offDeg) + (r.isEmpty() ? "" : "  " + r);
            }
            case FAR_LEFT:
                return g.record(s + "YawMaxDeg", String.format(Locale.US, "%.1f", limit(p, FAR_LEFT)));
            case FAR_RIGHT:
                return g.record(s + "YawMinDeg", String.format(Locale.US, "%.1f", limit(p, FAR_RIGHT)));
            default:
                return "";
        }
    }
}
